/// Proof: the pair commitment is exactly injective — equal commitments
/// imply equal inputs, over the full u64 x u64 domain.
pub proof fn combine_hashes_injective(
    a1: u64, b1: u64,
    a2: u64, b2: u64,
)
    requires combine_hashes_spec(a1, b1) == combine_hashes_spec(a2, b2)
    ensures a1 == a2 && b1 == b2
{
    let c1 = combine_hashes_spec(a1, b1);
    let c2 = combine_hashes_spec(a2, b2);
    // The low 64 bits of the commitment carry `a` exactly (a < 2^64, and
    // the `b << 64` part contributes zero to the low 64 bits).
    assert((c1 as u64) == (c2 as u64)) by(bit_vector);
    assert((c1 as u64) == a1) by(bit_vector);
    assert((c2 as u64) == a2) by(bit_vector);
    assert(a1 == a2);
    // The high 64 bits of the commitment carry `b` exactly.
    assert(((c1 >> 64) as u64) == ((c2 >> 64) as u64)) by(bit_vector);
    assert(((c1 >> 64) as u64) == b1) by(bit_vector);
    assert(((c2 >> 64) as u64) == b2) by(bit_vector);
    assert(b1 == b2);
}

