/// Proof: the pair commitment is exactly injective — equal commitments
/// imply equal inputs, over the full u64 x u64 domain.
pub proof fn combine_hashes_injective(
    a1: u64, b1: u64,
    a2: u64, b2: u64,
)
    requires combine_hashes_spec(a1, b1) == combine_hashes_spec(a2, b2)
    ensures a1 == a2 && b1 == b2
{
    // Low 64 bits of the commitment carry `a`; since a < 2^64 they are
    // exactly the low 64 bits of a, so equal commitments give a1 == a2.
    assert(
        ((a1 as u128) & 0xFFFF_FFFF_FFFF_FFFFu128)
            == ((a2 as u128) & 0xFFFF_FFFF_FFFF_FFFFu128)
    ) by(bit_vector);
    assert(a1 == a2) by(bit_vector);
    // High 64 bits of the commitment carry `b`; equal commitments give
    // b1 == b2.
    assert(
        (combine_hashes_spec(a1, b1) >> 64) & 0xFFFF_FFFF_FFFF_FFFFu128
            == (combine_hashes_spec(a2, b2) >> 64) & 0xFFFF_FFFF_FFFF_FFFFu128
    ) by(bit_vector);
    assert(b1 == b2) by(bit_vector);
